'use strict';
const D=window.LAB_DATA;
const STORAGE='english-lab-v1';
const $=(s,root=document)=>root.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
const defaults=()=>({answers:{},plan:{},drafts:{},checks:{},listening:{},scores:{},session:null,timer:null,exams:{}});
let state=defaults(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'null');if(raw&&raw.version===1&&raw.data&&typeof raw.data==='object'){state={...defaults(),...raw.data};for(const k of ['answers','plan','drafts','checks','listening','scores','exams'])if(!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))state[k]={};if(state.session&&(!Array.isArray(state.session.ids)||!Number.isInteger(state.session.index)||state.session.index<0||state.session.ids.some(id=>!D.questions.some(q=>q.id===id))))state.session=null;}}catch{storageOK=false;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({version:1,data:state}));return true;}catch{storageOK=false;notify('Der Browser kann gerade nicht speichern. Exportiere deine Texte und deinen Fortschritt.');return false;}}
let toastId;
function notify(message){const n=$('#notice');n.textContent=message;n.classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>n.classList.remove('show'),5000);}
const topic=id=>D.grammar.find(t=>t.id===id);
const year=y=>D.years.find(t=>t.year===Number(y))||D.years[0];
const asset=(file,page)=>`material/${encodeURIComponent(file)}${page?'#page='+page:''}`;
const pdfLink=(file,label,page)=>file?`<a href="${asset(file,page)}" target="_blank" rel="noopener">${E(label)} ↗</a>`:'';
const button=(label,action,kind='primary',extra='')=>`<button type="button" class="${kind}" data-action="${action}" ${extra}>${label}</button>`;
const head=(title,sub,kicker='')=>`${kicker?`<p class="section-label">${kicker}</p>`:''}<h1>${title}</h1><p class="intro">${sub}</p>`;
function stats(){let attempted=0,correct=0;for(const q of D.questions){const a=state.answers[q.id];if(a){attempted++;if(a.correct)correct++;}}return{attempted,correct};}
function weakTopics(){return D.grammar.map(t=>{const qs=D.questions.filter(q=>q.topic===t.id&&state.answers[q.id]);return{...t,attempted:qs.length,wrong:qs.filter(q=>!state.answers[q.id].correct).length};}).filter(t=>t.wrong).sort((a,b)=>b.wrong-a.wrong);}
function targetDays(){const now=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return Math.round((Date.UTC(2026,8,29)-Date.UTC(+p.year,+p.month-1,+p.day))/86400000);}
const days=targetDays();$('#countdown').textContent=days>0?`Noch ${days} ${days===1?'Tag':'Tage'} · 29.09.`:days===0?'Heute ist dein Testtag':'Weiterüben nach dem Test';
function home(){const s=stats(),weak=weakTopics(),done=Object.values(state.plan).filter(Boolean).length;return head('Schritt für Schritt zum Test.','Finde heraus, was schon sitzt. Übe deine Lücken und geh mit einem guten Gefühl in den 29. September.','Dein Lernweg · Schwerpunkt 2021–2025')+`
 <section class="hero-work"><div class="start"><span class="pill accent">Dein nächster Schritt</span><h2 style="margin-top:16px">${weak.length?'Hier kannst du sicherer werden.':s.attempted?'Bleib im Training.':'Was kannst du schon?'}</h2><p class="muted">${weak.length?`Bei <strong>${E(weak[0].title)}</strong> sind noch Fragen offen. Schau dir die Regel an und probiere es erneut.`:s.attempted?'Wende die Regeln auf neue Sätze an. Eine gemischte Runde gibt dir zwölf Aufgaben aus verschiedenen Themen.':'Starte mit zwölf neu entwickelten Fragen. Sie prüfen die wichtigen Grammatikthemen, ohne die Antworten der Originaltests vorwegzunehmen.'}</p><div class="actions">${button(weak.length?'Lücken gezielt üben':s.attempted?'Neue Übungsrunde starten':'Lerncheck starten',weak.length?'start:topic:'+weak[0].id:s.attempted?'start:mixed':'start:diagnostic')}<span class="meta">${weak.length?'Mit Erklärungen':s.attempted?'12 Aufgaben · ca. 15 Min.':'12 Aufgaben · ca. 15 Min.'}</span></div>${state.session&&state.session.index<state.session.ids.length?'<p class="small-gap"><a href="#quiz">Angefangene Übung fortsetzen</a></p>':''}</div><aside class="aside-note"><h3>So übst du wirksam</h3><ol><li>Erst selbst lösen.</li><li>Die Erklärung lesen.</li><li>Fehler später noch einmal versuchen.</li></ol><div class="progress-caption"><span>Zuletzt richtig gelöst</span><strong>${s.correct} / ${D.questions.length}</strong></div><progress value="${s.correct}" max="${D.questions.length}">${s.correct}</progress><p class="meta small-gap">${s.attempted?`${s.attempted} verschiedene Aufgaben bearbeitet.`:'Dein Fortschritt beginnt mit der ersten Antwort.'}</p></aside></section>
 <div class="split"><section><div class="row"><h2>Dein Plan bis zum 29.09.</h2><span class="pill" id="plan-count">${done} / 13 Einheiten</span></div><p class="meta">Vorschlag für 16.–28. September 2026. Später gestartet? Beginne mit dem Lerncheck und wähle deine Lücken.</p><div>${D.plan.map((p,i)=>`<div class="plan-row ${state.plan[i]?'done':''}"><input type="checkbox" id="day-${i}" data-plan="${i}" ${state.plan[i]?'checked':''}><span class="meta">${p[0]}</span><label for="day-${i}"><strong>${p[1]}</strong><span class="meta">${p[2]} · ${p[4]} Min.</span></label><a href="${planHref(p[3])}" class="button secondary">Öffnen</a></div>`).join('')}</div></section>
 <aside><div class="panel"><h3>Das erwartet dich im Test</h3><ul class="flat-list"><li><strong>Listening</strong><div class="meta">Nur in den Originaltests · 15 BE</div></li><li><strong>Use of English</strong><div class="meta">Grammatik sicher anwenden · 15 BE</div></li><li><strong>Sprachmittlung</strong><div class="meta">Wichtiges auf Englisch vermitteln · 20 BE</div></li></ul><p class="meta small-gap">Aufbau der bereitgestellten Septembertests 2021–2025: 60 Minuten, keine Hilfsmittel. Dein aktueller Test richtet sich nach den Vorgaben deiner Lehrkraft.</p></div><div class="panel tint"><h3>Deine Fehler sind ein Lernplan.</h3><p class="meta">${weak.length?`${weak.length} Themen bieten sich zum Wiederholen an.`:'Sobald du Fragen beantwortest, findest du hier passende Wiederholungen.'}</p>${weak.slice(0,3).map(t=>`<p><a href="#grammar/${t.id}">${t.title}</a><br><span class="meta">${t.wrong} offene ${t.wrong===1?'Aufgabe':'Aufgaben'}</span></p>`).join('')}<a href="#progress">Fortschritt ansehen</a></div></aside></div>`;}
function planHref(p){const [a,b]=p.split(':');if(['topic','year'].includes(a))return '#start/'+a+'/'+b;if(a==='diagnostic'||a==='mistakes'||a==='mixed')return '#start/'+a;return '#'+(a==='exams'?'exam':a)+(b?'/'+b:'');}
function practice(){const fresh=D.questions.filter(q=>!q.year).length;return head('Neue Aufgaben. Sicheres Wissen.','Übe dieselben Grammatikregeln in anderen Situationen. Jede Antwort bekommt eine Erklärung und einen Link zur passenden Regel.')+`
 <section class="panel tint"><h2>${fresh} eigenständige Übungen</h2><p>Neue Sätze zu Schule, Freizeit, Reisen und Alltag. Pro Thema kannst du Grundlagen festigen, Formen anwenden oder dein Wissen auf neue Zusammenhänge übertragen.</p><div class="actions">${button('Gemischte Runde starten','start:mixed')}${button('Lerncheck starten','start:diagnostic','secondary')}</div><p class="meta small-gap">Zwölf Aufgaben pro gemischter Runde. Noch nicht bearbeitete Fragen kommen zuerst; danach offene Fehler und bereits gelöste Fragen.</p></section>
 <h2>Ein Thema gezielt üben</h2><div class="filters"><div class="field"><label for="practice-topic">Dein Thema</label><select id="practice-topic">${D.grammar.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></div><div class="field"><label for="practice-level">Schwierigkeit</label><select id="practice-level"><option value="new">Alle neuen Übungen</option><option value="basic">Grundlagen festigen</option><option value="apply">Formen anwenden</option><option value="transfer">Wissen übertragen</option></select></div></div><div class="actions">${button('Thema üben','start-selected')}${button('Fehler wiederholen','start:mistakes','secondary')}</div><p class="meta small-gap">Bis zu zwölf Aufgaben pro Themenrunde. „Fehler wiederholen“ enthält deine offenen Fehler aus neuen Übungen und ausdrücklich gewähltem Originaltraining.</p>
 <details style="margin-top:32px"><summary>Originalaufgaben separat trainieren · 2021–2025</summary><p class="muted">Diese 75 Aufgaben stammen aus den Originaltests. Sie sind ausdrücklich kein neuer Übungsstoff. Für eine unverbrauchte Generalprobe übe zunächst mit den neuen Aufgaben oben.</p><div class="actions">${[2025,2024,2023,2022,2021].map(y=>button('Original '+y,'start:year:'+y,'secondary')).join('')}</div><p class="small-gap"><a href="#exams">Zu den vollständig ausfüllbaren Originaltests</a></p></details>
 <h2 style="margin-top:40px">Erst die Regel verstehen?</h2><div class="grammar-index">${D.grammar.map(t=>topicCard(t)).join('')}</div>`;}
function topicCard(t){return `<a class="topic-link" href="#grammar/${t.id}"><h3>${t.title} <span aria-hidden="true">↗</span></h3><p>${t.sub}</p><p class="meta small-gap">In den Tests: ${t.years.join(', ')}</p></a>`;}
function grammar(id){if(!id||!topic(id))return head('Kurz nachschlagen. Besser verstehen.','Vierzehn Kapitel helfen dir, Lücken aus früheren Klassen zu schließen. Die Beispiele zeigen dir die Regel direkt im Satz.')+`<div class="field"><label for="grammar-search">Thema finden</label><input id="grammar-search" type="search" placeholder="Zum Beispiel: Zeiten, if, Passiv, since …"></div><div class="grammar-index" id="grammar-results">${D.grammar.map(topicCard).join('')}</div>`;const t=topic(id);return `<a class="back" href="#grammar">← Alle Grammatikthemen</a><article class="lesson">${head(t.title,t.sub,`Nachschlagen · Testbezug ${t.years.join(', ')}`)}<p class="rule">${t.rule}</p><h2>Die Regel auf einen Blick</h2><ul>${t.forms.map(f=>`<li>${E(f)}</li>`).join('')}</ul><h2>So sieht das im Satz aus</h2>${t.examples.map(ex=>`<div class="example"><p lang="en">${E(ex[0])}</p><p class="muted">${E(ex[1])}</p></div>`).join('')}<div class="warning"><strong>Typische Stolperfalle</strong><p style="margin:8px 0 0">${E(t.trap)}</p></div><div class="actions">${button('Jetzt dazu üben','start:topic:'+id)}${state.session&&state.session.index<state.session.ids.length?'<a href="#quiz">Zur laufenden Übung</a>':''}</div></article>`;}
function practicePriority(q){const a=state.answers[q.id];return !a?0:a.correct?2:1;}
function shuffled(list){const result=[...list];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
function orderedPractice(list){return shuffled(list).sort((a,b)=>practicePriority(a)-practicePriority(b));}
function questionSet(kind,value,level='new'){
 if(kind==='diagnostic'){const ids=['n-tenses-05','n-conditionals-08','n-reported-07','n-passive-06','n-ing-08','n-participles-04','n-modals-05','n-comparison-09','n-quantifiers-09','n-prepositions-10','n-relatives-08','n-possessive-06'];return ids.map(id=>D.questions.find(q=>q.id===id));}
 if(kind==='mixed'){const candidates=D.grammar.map(t=>orderedPractice(D.questions.filter(q=>!q.year&&q.topic===t.id))[0]).filter(Boolean);return orderedPractice(candidates).slice(0,12);}
 if(kind==='year')return D.questions.filter(q=>q.year===+value);
 if(kind==='topic')return orderedPractice(D.questions.filter(q=>!q.year&&q.topic===value&&(level==='new'||level==='all'||q.level===level))).slice(0,12);
 if(kind==='mistakes')return D.questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct);
 return [];
}
function startSession(kind,value,level){const qs=questionSet(kind,value,level);if(!qs.length){notify(kind==='mistakes'?'Noch keine offenen Fehler. Starte zuerst eine Übung.':'Für diese Auswahl gibt es keine Aufgaben.');go('practice');return;}state.session={kind,value,ids:qs.map(q=>q.id),index:0,responses:{},started:new Date().toISOString()};save();go('quiz');}
function normalize(v,caseSensitive=false){let s=String(v).trim().replace(/[‘’`]/g,"'").replace(/\s+/g,' ').replace(/[.!?]$/,'');return caseSensitive?s:s.toLowerCase();}
function matchAnswer(q,value){return q.answers.some(a=>normalize(a,q.caseSensitive)===normalize(value,q.caseSensitive));}
function quiz(){const ses=state.session;if(!ses)return head('Womit möchtest du starten?','Wähle eine Übung, um deine Grammatikkenntnisse zu festigen.')+'<a class="button" href="#practice">Übung auswählen</a>';if(ses.index>=ses.ids.length)return results();const q=D.questions.find(q=>q.id===ses.ids[ses.index]),r=ses.responses[q.id],t=topic(q.topic);const title=ses.kind==='diagnostic'?'Dein Lerncheck':ses.kind==='mixed'?'Neue gemischte Übungsrunde':ses.kind==='year'?'Originaltraining '+ses.value:ses.kind==='mistakes'?'Deine Fehlerwerkstatt':t.title;return `<a class="back" href="#practice">← Zur Übungsauswahl</a>${head(title,ses.kind==='diagnostic'?'Versuche es zuerst ohne Hilfe. Der Lerncheck ist keine Note.':'Beachte den Arbeitsauftrag. Bei Schreibweisen zählen britische und amerikanische Varianten, soweit angegeben.')}<div class="progress-caption"><span>Aufgabe ${ses.index+1} von ${ses.ids.length}</span><span>${Math.round(ses.index/ses.ids.length*100)} % bearbeitet</span></div><progress value="${ses.index}" max="${ses.ids.length}"></progress><div class="study-grid" style="margin-top:24px"><section class="exercise"><p class="meta">${E(q.source)}</p>${q.instruction?`<p class="meta">${E(q.instruction)}</p>`:''}<p class="sentence" lang="en">${E(q.prompt).replace('___','<strong aria-label="Lücke">________</strong>')}</p><form id="answer-form"><div class="field answer-input"><label for="answer">Deine Antwort</label><input type="text" id="answer" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" ${r?'readonly':''} value="${E(r?.answer||(ses.inputDraftIndex===ses.index?ses.inputDraft:'')||'')}" aria-describedby="answer-hint"></div><p id="answer-hint" class="meta small-gap">${q.instruction?'Trage die gefragte Form, Wortgruppe oder Auswahl ein.':'Nur das fehlende Wort oder die fehlende Wortgruppe eintragen.'}</p><div class="actions">${r?button(ses.index===ses.ids.length-1?'Auswertung ansehen':'Nächste Aufgabe','next'): '<button type="submit" class="primary">Antwort prüfen</button>'+button('Überspringen','skip','secondary')}</div></form>${r?feedback(q,r):'<div id="answer-feedback" aria-live="polite"></div>'}</section><aside><div class="panel tint"><h3>Passende Grammatik</h3><p>${E(t.sub)}</p><a href="#grammar/${t.id}">${E(t.title)} nachschlagen</a><p class="meta small-gap">Deine Übung bleibt erhalten.</p></div><p class="meta">${q.year?'Diese Aufgabe stammt aus einem Originaltest und wurde für das Einzeltraining aufbereitet. Den vollständigen Test findest du unter „Originaltests online“.':'Diese Aufgabe wurde neu entwickelt. Sie übt prüfungsrelevante Regeln mit einem anderen Satz oder Kontext.'}</p></aside></div>`;}
function feedback(q,r){return `<div class="feedback ${r.correct?'correct':''}" id="answer-feedback" role="status"><h3>${r.correct?'Richtig gelöst.':'Hier steckt eine wichtige Regel.'}</h3>${!r.correct?`<p>Passende Antwort: <strong lang="en">${E(q.answers[0])}</strong></p>`:''}<p>${E(q.explanation)}</p>${q.answers.length>1?`<p class="meta">Auch akzeptiert: ${q.answers.slice(1).map(E).join(' · ')}</p>`:''}<a href="#grammar/${q.topic}">Regel nachschlagen</a></div>`;}
function checkAnswer(value){const s=state.session;if(!s||s.index>=s.ids.length)return;const q=D.questions.find(q=>q.id===s.ids[s.index]);if(s.responses[q.id])return;if(!value.trim()){notify('Trage zuerst eine Antwort ein oder überspringe die Aufgabe.');$('#answer')?.focus();return;}const correct=matchAnswer(q,value),r={answer:value,correct,at:new Date().toISOString()};s.responses[q.id]=r;const old=state.answers[q.id];state.answers[q.id]={...r,attempts:(old?.attempts||0)+1,firstCorrect:old?.firstCorrect??correct};save();render(false);$('#answer-feedback')?.scrollIntoView({block:'nearest'});$('.actions button[data-action="next"]')?.focus();}
function results(){const s=state.session;const qs=s.ids.map(id=>D.questions.find(q=>q.id===id));const correct=qs.filter(q=>s.responses[q.id]?.correct).length;const missed=qs.filter(q=>!s.responses[q.id]?.correct);const skipped=qs.filter(q=>!s.responses[q.id]).length;const topics=[...new Set(missed.map(q=>q.topic))];return head('Deine nächste Übung steht fest.','Nutze die Auswertung als Orientierung. Ein Fehler zeigt dir, was du als Nächstes lernen kannst.')+`<section class="panel tint"><p class="result-number">${correct} von ${qs.length} richtig</p><p>${skipped?`${skipped} Aufgaben übersprungen. `:''}${correct===qs.length?'Diese Runde sitzt. Probiere eine neue gemischte Runde, um dein Wissen in anderen Situationen anzuwenden.':'Lies die Erklärungen und wiederhole die offenen Themen später noch einmal.'}</p><p class="meta">Ergebnis dieser Runde. Keine offizielle Testnote und keine sichere Vorhersage für die Prüfung.</p></section>${topics.length?`<h2>Diese Themen lohnen sich</h2><div class="grammar-index">${topics.map(id=>topicCard(topic(id))).join('')}</div>`:''}<h2 style="margin-top:32px">Deine Antworten</h2>${qs.map(q=>{const r=s.responses[q.id];return `<details><summary>${r?.correct?'✓ Richtig':r?'↻ Wiederholen':'○ Übersprungen'} · ${E(topic(q.topic).title)}</summary><p lang="en">${E(q.prompt)}</p><p>Deine Antwort: ${E(r?.answer||'keine Antwort')}</p><p>Passende Antwort: <strong>${E(q.answers[0])}</strong></p><p>${E(q.explanation)}</p></details>`;}).join('')}<div class="actions">${missed.length?button('Offene Aufgaben erneut üben','retry'):''}<a class="button secondary" href="#home">Zum Lernweg</a><a href="#practice">Andere Übung wählen</a></div>`;}
function yearSelect(id,selected,includeOld=false){return `<div class="field year-select"><label for="${id}">Jahrgang</label><select id="${id}">${D.years.filter(y=>includeOld||y.year>=2021).map(y=>`<option value="${y.year}" ${y.year===selected?'selected':''}>${y.year} · ${E(id==='writing-year'?y.writing:y.listening)}</option>`).join('')}</select></div>`;}
function audioBlock(y){return y.audio?`<audio controls preload="none" aria-label="Hörtext Jahrgangsstufentest ${y.year}" src="${asset(y.audio)}">Dein Browser unterstützt Audio nicht.</audio><p class="meta">${pdfLink(y.audio,'Hördatei separat öffnen')} · Im Übungsmodus darfst du pausieren und zurückspringen.</p>`:'<p>Für diesen Jahrgang wurde keine Hördatei bereitgestellt.</p>';}
function listening(){return head('Hörverstehen gehört zur Prüfung.','Die Hörtexte und Aufgaben bearbeitest du ausschließlich in den Originaltests. So hörst du sie bei deiner Generalprobe zum ersten Mal.')+'<a class="button" href="#exams">Zu den Originaltests</a>'; }
function writing(id){const selected=id||'2025';const extra=String(selected).startsWith('extra');const y=year(extra?selected.slice(-4):selected);const key=extra?'extra'+y.year:String(y.year);const title=extra?(y.year===2025?'Do influencers inspire or frustrate you?':'Would you take part in a digital detox week?'):y.writing;const target=extra?(y.year===2025?180:200):y.words;const task=extra?y.files.find(f=>f.includes('Textprod_2')):y.task;const checks=extra?['Eine klare eigene Position formuliert','Argumente erklärt und mit Beispielen gestützt','Gedanken sinnvoll in Absätze gegliedert','Einleitung und Schluss geschrieben','Zeiten, Wortstellung und Rechtschreibung geprüft']:['Adressaten, Textsorte und Auftrag beachtet','Alle geforderten Inhaltsaspekte aufgenommen','Nur relevante Informationen ausgewählt','Eigene englische Formulierungen statt Satz-für-Satz-Übersetzung','Passende Überschrift bzw. E-Mail-Rahmen gesetzt','Absätze und sinnvolle Verknüpfungen verwendet','Zeiten, Satzbau und Rechtschreibung geprüft'];const instructions={2025:'Schreibe für die Online-Plattform „Timeless Art“ einen Artikel über die Zeitpyramide: Projekt, Konzept und Faszination für die Betrachtenden. Nutze die Angaben des Ausgangstexts, einschließlich seines damaligen Zeitstands.',2024:'Schreibe für eine englische Schülerzeitung einen Artikel über das Abendbrot: Beschreibung, Ursprung, Gründe für den Rückgang und warum der Brauch weiterlebt.',2023:'Schreibe einen Artikel für „School’s over, what now?“: allgemeine Informationen, Vorteile und Probleme des Bundesfreiwilligendiensts.',2022:'Stelle „Spende dein Pfand“ auf einer englischen Projektwebseite vor: Funktionsweise, Vorteile und Veränderungen im Leben Uwe Trögers.',2021:'Stelle „Klassenzimmer unter Segeln“ in einem englischen Artikel vor: Grundzüge, Teilnahme, Bordalltag und nötiger Verzicht.'};return head('Gute Texte beginnen mit einem Plan.','Lies den Auftrag, wähle wichtige Informationen aus und schreibe in deinen eigenen Worten. Deine Entwürfe werden hier auf dem Gerät gespeichert.')+`<div class="field year-select"><label for="writing-year">Schreibaufgabe</label><select id="writing-year">${D.years.filter(y=>y.year>=2021).map(a=>`<option value="${a.year}" ${selected==a.year?'selected':''}>${a.year} · ${a.writing}</option>`).join('')}<option value="extra2025" ${selected==='extra2025'?'selected':''}>Zusatz 2025 · Influencers</option><option value="extra2024" ${selected==='extra2024'?'selected':''}>Zusatz 2024 · Digital detox</option></select></div><section class="panel tint"><span class="pill">${extra?'Zusatztraining · separater Sommer-Test':'Sprachmittlung · Septembertest '+y.year}</span><h2 style="margin-top:16px">${E(title)}</h2><p>${extra?'Write a coherent comment. Explain your point of view, support it with examples and organise your ideas in paragraphs.':instructions[y.year]||'Beachte den Auftrag im Original-PDF.'}</p><p class="meta">${extra&&y.year===2025?'Mindestens':'Etwa'} ${target} Wörter · ${extra?'30–35':'ca. 30'} Minuten als Übungsrichtwert</p>${pdfLink(task,'Originalauftrag mit Ausgangsmaterial öffnen',extra?2:y.page)}</section><div class="writing-layout"><section><h2>Material & Planung</h2>${!extra?`<details><summary>Ausgangstext hier lesen</summary><p class="meta">Textauszug aus dem Original-PDF. Bei ungewöhnlichen Zeilenumbrüchen oder Abbildungen bitte das PDF verwenden.</p><div class="transcript">${E(y.writingText)}</div></details>`:''}<label for="writing-plan">Deine Stichpunkte</label><textarea id="writing-plan" data-draft="${key}:plan" placeholder="Für wen schreibe ich?&#10;Was muss unbedingt hinein?&#10;Wie ordne ich die Absätze?">${E(state.drafts[key+':plan']||'')}</textarea><details><summary>Formulierungen, die helfen</summary><ul><li lang="en">The project aims to …</li><li lang="en">One important advantage is …</li><li lang="en">However, there are also …</li><li lang="en">For example, …</li><li lang="en">As a result, …</li><li lang="en">Overall, …</li></ul><p class="meta">Bei einer Sprachmittlung keine eigene Meinung ergänzen, wenn der Auftrag sie nicht verlangt. Unbekannte deutsche Begriffe kurz erklären.</p></details></section><section><div class="row"><h2>Dein englischer Text</h2><span class="pill count" id="word-count">${wordCount(state.drafts[key+':text']||'')} Wörter</span></div><label class="meta" for="writing-text">${extra?'Kommentar':'Ausformulierter Entwurf'} (${extra&&y.year===2025?'mindestens':'ca.'} ${target} Wörter)</label><textarea id="writing-text" data-draft="${key}:text" lang="en" spellcheck="true" placeholder="Write your text here …">${E(state.drafts[key+':text']||'')}</textarea><p class="meta" id="save-status">${storageOK?'Auf diesem Gerät gespeichert.':'Speichern nicht verfügbar. Bitte Text herunterladen.'}</p><div class="actions">${button('Text herunterladen','export-writing:'+key,'secondary')}${button('Text kopieren','copy-writing:'+key,'secondary')}</div></section></div><section class="panel" style="margin-top:32px"><h2>Jetzt selbst überarbeiten</h2><ul class="checklist">${checks.map((c,i)=>`<li><label><input type="checkbox" data-check="${key}:${i}" ${state.checks[key+':'+i]?'checked':''}>${E(c)}</label></li>`).join('')}</ul><details><summary>Erwartungshorizont & Bewertung</summary><p>Vergleiche zuerst Inhalt und Aufbau, anschließend die Sprache. Die Plattform benotet deinen freien Text nicht automatisch.</p>${extra?'<p>Der Sommer-Test verwendet ein Raster mit 4 BE für Inhalt/Textstruktur und 6 BE für Sprache.</p>':'<p>In den Septembertests 2021–2025: Inhalt bis 4 BE, Sprache bis 6 BE. Die Summe wird verdoppelt (maximal 20 BE). Eine Selbsteinschätzung ersetzt keine Rückmeldung deiner Lehrkraft.</p>'}${pdfLink(extra?y.files.find(f=>f.includes('Loes_2')):y.solution,extra?'Bewertungsraster öffnen':'Offiziellen Erwartungshorizont öffnen',extra?2:4)}${!extra&&y.year===2025?'<p class="small-gap">Kontrollpunkte: Manfred Laber, Beginn 1993, Wemding, 120 Blöcke, ein Block alle zehn Jahre, geplantes Ende 3183; Nachdenken über Zeit, ungewisse Vollendung und Weitergabe an kommende Generationen. Die Angaben beziehen sich auf den Originaltext.</p>':''}${!extra&&y.year===2024?'<p class="small-gap">Kontrollpunkte: kaltes Abendessen mit Brot und Belag; Ursprung in Industrie und Kantinen; schnelle Zubereitung; veränderte Essgewohnheiten; Fortbestand bei Älteren, Familien und in Teilen der Stadtkultur.</p>':''}</details></section>`;}
function wordCount(t){return(t.trim().match(/\S+/g)||[]).length;}
function exams(id){const y=year(id||2025);return head('Die Generalprobe beginnt hier.','Bearbeite einen vollständigen Originaltest. Nutze erst danach die Lösungen und notiere, was du noch wiederholen möchtest.')+yearSelect('exam-year',y.year)+`<section class="panel"><div class="row"><div><h2>Originaltest ${y.year}</h2><p class="muted">60 Minuten · Listening 15 BE · Use of English 15 BE · Sprachmittlung 20 BE</p></div><span class="pill accent">Schwerpunkt</span></div><div class="material-links">${pdfLink(y.task,'Aufgaben-PDF öffnen')}${pdfLink(y.solution,'Lösungen nach der Bearbeitung öffnen')}</div>${audioBlock(y)}<details><summary>So funktioniert die Generalprobe</summary><ol><li>Öffne oder drucke die Aufgaben. Lege Papier und Stift bereit.</li><li>Starte die 60 Minuten und den vollständigen Hörtrack. Der Track enthält die Wiederholungen bereits.</li><li>Arbeite danach an Grammatik und Sprachmittlung. Die Zeit umfasst den gesamten Test.</li><li>Keine Nachschlagehilfe während der Generalprobe. Beim Üben darfst du dir zusätzliche Zeit nehmen.</li><li>Vergleiche anschließend mit den offiziellen Lösungen.</li></ol></details><div class="timer"><output id="timer-output" aria-label="Verbleibende Übungszeit">${timerLabel()}</output>${button(state.timer?.running?'Timer pausieren':'60-Minuten-Timer starten / fortsetzen','timer-toggle','secondary')}${button('Timer zurücksetzen','timer-reset','text')}</div><p class="meta small-gap">Der Timer ist eine Lernhilfe. Er läuft bei einem Seitenwechsel oder Neuladen weiter und beendet deine Arbeit nicht automatisch. Bei einer Pause hältst du den Hörtrack selbst an.</p><div id="timer-status" role="status"></div></section><section class="panel"><h2>Deine Selbstauswertung</h2><p class="meta">Trage die mit dem offiziellen Schlüssel ermittelten Punkte ein. Für die Sprachmittlung ist Feedback durch die Lehrkraft besonders hilfreich.</p>${[['listening','Hörverstehen',15],['grammar','Use of English',15],['writing','Sprachmittlung (bereits × 2)',20]].map(([k,l,m])=>`<div class="score-row"><label for="score-${k}">${l} · maximal ${m} BE</label><input id="score-${k}" type="number" min="0" max="${m}" step="${k==='grammar'?1:.5}" data-score="${y.year}:${k}" value="${state.scores[y.year+':'+k]??''}"></div>`).join('')}<p id="score-total" role="status">${scoreText(y.year)}</p><p class="meta">Diese selbst eingetragenen Punkte sind keine automatisch geprüfte Bewertung.</p></section><h2>Alle Materialien ab 2021</h2>${D.years.filter(y=>y.year>=2021).map(materialRow).join('')}<details style="margin-top:32px"><summary>Älteres Zusatzmaterial: 2018 und 2019</summary><p class="meta">Freiwillige Ergänzung. Die Vorbereitung oben konzentriert sich auf 2021–2025. Ältere Punktzahlen und Formate können abweichen.</p>${D.years.filter(y=>y.year<2021).map(materialRow).join('')}</details><p class="source-note">Quelle: die bereitgestellten Jahrgangsstufentests Englisch am Gymnasium und zugehörigen Lösungshinweise. Die Datei „Ergebnisse 2024“ enthält eine Ergebnisübersicht, keine persönlichen Lerndaten. Sommer-Textproduktion ist Zusatztraining und kein zusätzlicher Teil des Septembertests. Es wurden keine Materialien für 2020 bereitgestellt.</p>`;}
function materialLabel(file){if(file.endsWith('.mp3'))return'Hördatei';if(file.includes('Aufg'))return'Originalaufgaben';if(file.includes('Ergeb'))return'Ergebnisübersicht';if(file.includes('Loes_2'))return'Bewertungsraster Zusatztest';if(file.includes('Loes'))return'Lösungen Septembertest';if(file.includes('Textprod_2'))return'Zusatztest Schreiben';if(file.includes('Textprod'))return'Zusatztest Schreiben mit Raster';return file;}
function materialRow(y){return `<article class="material-row"><div class="material-year">${y.year}</div><div><h3>${E(y.listening)}</h3><p class="meta">Sprachmittlung: ${E(y.writing)}</p>${y.year===2018?'<p class="meta">Nur Aufgaben vorhanden. Hördatei und offizieller Lösungsschlüssel fehlen.</p>':''}<div class="material-links">${y.files.map(f=>pdfLink(f,materialLabel(f))).join('')}</div>${y.year>=2021?`<div class="actions"><a class="button secondary" href="#exam/${y.year}">Originaltest online ausfüllen</a><a href="#start/year/${y.year}">Grammatik einzeln üben</a><a href="#writing/${y.year}">Schreibaufgabe bearbeiten</a></div>`:''}</div></article>`;}
function scoreText(y){const vals=['listening','grammar','writing'].map(k=>state.scores[y+':'+k]);if(vals.some(v=>v===''||v===undefined))return'Trage alle drei Bereiche ein, um die Summe zu sehen.';const nums=vals.map(Number);if(nums.some((v,i)=>!Number.isFinite(v)||v<0||v>[15,15,20][i]||(i===1?!Number.isInteger(v):v*2%1)))return'Bitte gültige Punktzahlen innerhalb der Grenzen eintragen.';return`Deine Selbsteinschätzung: ${nums.reduce((a,b)=>a+b,0).toLocaleString('de-DE')} von 50 BE.`;}
function progressPage(){const s=stats();return head('Dein Fortschritt gehört dir.','Alle Angaben bleiben in diesem Browser auf diesem Gerät. Beim Löschen der Browserdaten gehen sie verloren. Es gibt keine Übertragung an deine Lehrkraft.')+`<section class="panel"><h2>${s.correct} Aufgaben zuletzt richtig gelöst</h2><p>${s.attempted} von ${D.questions.length} Aufgaben bearbeitet. Wiederholungen zählen nicht mehrfach.</p><progress value="${s.correct}" max="${D.questions.length}"></progress><p class="meta small-gap">Ein richtig wiederholter Fehler erscheint nicht mehr in der Fehlerwerkstatt.</p><div class="actions">${button('Fehler wiederholen','start:mistakes')}${button('Lernstand herunterladen','export-progress','secondary')}</div></section><h2>Deine Themen im Überblick</h2><ul class="flat-list">${D.grammar.map(t=>{const qs=D.questions.filter(q=>q.topic===t.id),a=qs.filter(q=>state.answers[q.id]),c=a.filter(q=>state.answers[q.id].correct);return`<li><div class="row"><div><a href="#grammar/${t.id}">${t.title}</a><div class="meta">${a.length?`${c.length} zuletzt richtig · ${a.length} bearbeitet`:'Noch nicht geübt'}</div></div><a href="#start/topic/${t.id}">Üben</a></div></li>`;}).join('')}</ul><section class="panel" style="margin-top:32px"><h2>Daten auf diesem Gerät</h2><p class="meta">Gespeichert werden Antworten, vollständige Online-Testbögen, angehakte Lerntage, Hörnotizen, Schreibentwürfe, selbst eingetragene Punkte und die Timer. Kein Name erforderlich. An einem gemeinsam genutzten Gerät können andere diese Inhalte sehen.</p><p class="meta">${storageOK?'Lokales Speichern ist verfügbar.':'Lokales Speichern ist derzeit nicht verfügbar. Nutze die Downloads, bevor du die Seite schließt.'}</p><details><summary>Gesamten Lernstand zurücksetzen</summary><p>Damit löschst du auch alle hier gespeicherten Texte und Hörnotizen. Lade sie vorher herunter.</p>${button('Alle lokalen Lerndaten endgültig löschen','reset-progress','secondary')}</details></section>`;}
function timerSeconds(){if(!state.timer)return 3600;return state.timer.running?Math.max(0,Math.ceil((state.timer.deadline-Date.now())/1000)):Math.max(0,state.timer.remaining??3600);}
function timerLabel(){const s=timerSeconds();return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function toggleTimer(){const remaining=timerSeconds();if(state.timer?.running)state.timer={running:false,remaining};else state.timer={running:true,deadline:Date.now()+(remaining||3600)*1000};save();render(false);}
setInterval(()=>{const el=$('#timer-output');if(el)el.textContent=timerLabel();if(state.timer?.running&&timerSeconds()===0){state.timer={running:false,remaining:0};save();notify('Die 60 Minuten sind um. Beende deine Generalprobe und prüfe deine Antworten.');if($('#timer-status'))$('#timer-status').textContent='Die Übungszeit ist abgelaufen.';}},1000);
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function render(focus=true){const [route='home',a,b]=location.hash.slice(1).split('/');if(route==='start'){startSession(a,b);return;}const makers={home,practice,grammar,listening,writing,exams:onlineExamLibrary,exam:onlineTest,progress:progressPage,quiz};const maker=makers[route]||home;$('#main').innerHTML=maker(a);document.querySelectorAll('[data-nav]').forEach(n=>{const active=n.dataset.nav===(route==='quiz'?'practice':route==='exam'?'exams':route);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0);} }
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function writingExport(key){return`English Lab · Schreibübung ${key}\n\nPlanung\n${state.drafts[key+':plan']||''}\n\nText (${wordCount(state.drafts[key+':text']||'')} Wörter)\n${state.drafts[key+':text']||''}`;}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const [action,a,v]=b.dataset.action.split(':');if(action==='start'){startSession(a,v);return;}if(action==='start-selected'){startSession('topic',$('#practice-topic').value,$('#practice-level').value);return;}if(action==='next'||action==='skip'){state.session.index++;save();render();return;}if(action==='retry'){const s=state.session;const ids=s.ids.filter(id=>!s.responses[id]?.correct);state.session={kind:'mistakes',ids,index:0,responses:{},started:new Date().toISOString()};save();render();return;}if(action==='timer-toggle'){toggleTimer();return;}if(action==='timer-reset'){if(window.confirm('Timer auf 60 Minuten zurücksetzen?')){state.timer=null;save();render(false);}return;}if(action==='export-writing'){download('English-Lab-Schreibtext-'+a+'.txt',writingExport(a));return;}if(action==='copy-writing'){try{await navigator.clipboard.writeText(state.drafts[a+':text']||'');notify('Text kopiert.');}catch{notify('Kopieren ist nicht verfügbar. Nutze „Text herunterladen“.');}return;}if(action==='export-listening'){const items=D.listeningItems[a];const text=items?items.map((it,i)=>`${i+1}. ${it[0]}\n${state.listening[a+':'+i]||'—'}`).join('\n\n'):state.listening[a+':notes']||'';download('English-Lab-Listening-'+a+'.txt',text);return;}if(action==='export-progress'){const s=stats();download('English-Lab-Lernstand.txt',`English Lab · Lernstand vom ${new Date().toLocaleDateString('de-DE')}\n${s.correct} zuletzt richtig, ${s.attempted} bearbeitet.\n\n`+D.questions.filter(q=>state.answers[q.id]).map(q=>`${state.answers[q.id].correct?'Richtig':'Wiederholen'}: ${q.prompt}\nDeine Antwort: ${state.answers[q.id].answer}\nRegel: ${q.explanation}`).join('\n\n')+'\n\nSCHREIBENTWÜRFE\n'+Object.entries(state.drafts).map(([k,v])=>k+'\n'+v).join('\n\n')+'\n\nHÖRNOTIZEN\n'+Object.entries(state.listening).map(([k,v])=>k+': '+v).join('\n')+'\n\nABGEHAKTE LERNTAGE\n'+D.plan.filter((p,i)=>state.plan[i]).map(p=>p[0]+' '+p[1]).join('\n'));return;}if(action==='reset-progress'&&window.confirm('Alle Antworten, Texte, Notizen und Fortschritte auf diesem Gerät endgültig löschen?')){state=defaults();save();render();notify('Dein lokaler Lernstand wurde gelöscht.');}});
document.addEventListener('submit',event=>{if(event.target.id==='answer-form'){event.preventDefault();checkAnswer($('#answer').value);}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='answer'&&state.session&&!el.readOnly){state.session.inputDraft=el.value;state.session.inputDraftIndex=state.session.index;save();}if(el.dataset.draft){state.drafts[el.dataset.draft]=el.value;const ok=save();if(el.id==='writing-text')$('#word-count').textContent=wordCount(el.value)+' Wörter';$('#save-status').textContent=ok?'Auf diesem Gerät gespeichert.':'Speichern nicht verfügbar. Bitte Text herunterladen.';}if(el.dataset.listen){state.listening[el.dataset.listen]=el.value;save();}if(el.dataset.score){state.scores[el.dataset.score]=el.value;save();$('#score-total').textContent=scoreText(el.dataset.score.split(':')[0]);}if(el.id==='grammar-search'){const val=el.value.toLocaleLowerCase('de');const matches=D.grammar.filter(t=>JSON.stringify(t).toLocaleLowerCase('de').includes(val));$('#grammar-results').innerHTML=matches.length?matches.map(topicCard).join(''):'<p class="empty">Kein Thema gefunden. Versuche „Zeiten“, „if“ oder „Gerund“.</p>';}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.plan!==undefined){state.plan[el.dataset.plan]=el.checked;save();el.closest('.plan-row').classList.toggle('done',el.checked);if($('#plan-count'))$('#plan-count').textContent=Object.values(state.plan).filter(Boolean).length+' / 13 Einheiten';}if(el.dataset.check){state.checks[el.dataset.check]=el.checked;save();}const routes={'listening-year':'listening','writing-year':'writing','exam-year':'exams'};if(routes[el.id])go(routes[el.id]+'/'+el.value);});
// Keep an unsubmitted answer when consulting a rule or navigating away.
window.addEventListener('hashchange',()=>render());
render(false);
// Optional native agent interface; shares the visible practice flow.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_grammar_practice',title:'Grammatikübung starten',description:'Öffnet eine Grammatikübung zu einem verfügbaren Thema und ersetzt die laufende Übungsrunde. Bereits gespeicherte Ergebnisse bleiben erhalten.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:D.grammar.map(t=>t.id)}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='topic')||!topic(input.topic))throw new Error('Unbekanntes Grammatikthema.');startSession('topic',input.topic);render(false);return{topic:input.topic,questions:state.session.ids.length};}})).catch(()=>{});}catch{}}
